//! Renderer-neutral `SpacetimeDB` client and generated Poche module bindings.

#![allow(
    clippy::missing_errors_doc,
    clippy::missing_panics_doc,
    clippy::wildcard_imports
)]

// Generated by `spacetime generate`; keep it reproducible instead of hand-editing it
// to satisfy lints that are stricter than the generator's own output.
#[allow(clippy::all, clippy::pedantic, missing_docs)]
pub mod module_bindings;

use module_bindings::*;
use spacetimedb_sdk::{DbContext, Identity, Table, TableWithPrimaryKey, credentials};
use std::fmt;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Condvar, Mutex, mpsc};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

pub const DEFAULT_URI: &str = "http://127.0.0.1:3000";
pub const DEFAULT_DATABASE: &str = "poche-desktop-v1";

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ClientConfig {
    pub uri: String,
    pub database: String,
    /// Immutable local account identifier used only to locate a protected token.
    pub account_id: String,
}

impl ClientConfig {
    #[must_use]
    pub fn local(account_id: impl Into<String>) -> Self {
        Self {
            uri: std::env::var("POCHE_SPACETIMEDB_URI").unwrap_or_else(|_| DEFAULT_URI.into()),
            database: std::env::var("POCHE_SPACETIMEDB_DATABASE")
                .unwrap_or_else(|_| DEFAULT_DATABASE.into()),
            account_id: account_id.into(),
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RoomCapability {
    pub room_id: String,
    pub join_code: String,
}

impl RoomCapability {
    pub fn generate() -> Result<Self, ClientError> {
        let mut bytes = [0_u8; 24];
        getrandom::fill(&mut bytes).map_err(|error| ClientError::Random(error.to_string()))?;
        let room_id = format!("room-{}", encode_hex(&bytes[..16], false));
        let encoded = encode_hex(&bytes[16..], true);
        let join_code = format!(
            "PCH-{}-{}-{}-{}",
            &encoded[0..4],
            &encoded[4..8],
            &encoded[8..12],
            &encoded[12..16]
        );
        Ok(Self { room_id, join_code })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ConnectionState {
    Connecting,
    Connected,
    Ready,
    Disconnected,
    Failed(String),
}

#[derive(Clone, Debug)]
pub enum ClientEvent {
    Connected {
        identity: String,
    },
    Ready,
    ModelChanged,
    CommandFinished {
        request_id: u64,
        operation: &'static str,
        elapsed: Duration,
        result: Result<(), String>,
    },
    Disconnected {
        reason: Option<String>,
    },
    Error(String),
}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct ClientSnapshot {
    pub identity: Option<String>,
    pub room_capability: Option<RoomCapability>,
    pub rooms: Vec<RoomView>,
    pub members: Vec<MemberView>,
    pub hand: Vec<HandCardView>,
    pub card_poses: Vec<CardPoseView>,
    pub game: Option<GameView>,
    pub revealed_cards: Vec<RevealedCardView>,
    pub activity: Vec<ActivityView>,
}

impl ClientSnapshot {
    #[must_use]
    pub fn room_id(&self) -> Option<&str> {
        self.rooms.first().map(|room| room.room_id.as_str())
    }

    #[must_use]
    pub fn own_seat(&self) -> Option<u8> {
        let identity = self.identity.as_deref()?;
        self.members
            .iter()
            .find(|member| member.identity == identity)
            .and_then(|member| member.seat)
    }

    /// Return the face this exact viewer is authorized to render.
    #[must_use]
    pub fn visible_card_face(&self, card_key: &str) -> Option<&str> {
        self.hand
            .iter()
            .find(|card| card.card_key == card_key)
            .map(|card| card.face.as_str())
            .or_else(|| {
                self.revealed_cards
                    .iter()
                    .find(|card| card.card_key == card_key)
                    .map(|card| card.face.as_str())
            })
    }
}

