#[derive(Debug)]
pub enum ClientError {
    Connect(String),
    Timeout(String),
    Credentials(String),
    Random(String),
    Request(String),
}

impl fmt::Display for ClientError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Connect(message) => write!(formatter, "connection failed: {message}"),
            Self::Timeout(message) => write!(formatter, "timed out: {message}"),
            Self::Credentials(message) => write!(formatter, "credential error: {message}"),
            Self::Random(message) => write!(formatter, "randomness unavailable: {message}"),
            Self::Request(message) => write!(formatter, "request failed: {message}"),
        }
    }
}

impl std::error::Error for ClientError {}

#[derive(Debug)]
struct Lifecycle {
    state: ConnectionState,
    identity: Option<String>,
}

struct ClientInner {
    connection: DbConnection,
    worker: Mutex<Option<JoinHandle<()>>>,
    lifecycle: Arc<(Mutex<Lifecycle>, Condvar)>,
    event_tx: mpsc::Sender<ClientEvent>,
    event_rx: Mutex<mpsc::Receiver<ClientEvent>>,
    next_request: AtomicU64,
}

impl Drop for ClientInner {
    fn drop(&mut self) {
        let _ = self.connection.disconnect();
        if let Some(worker) = self.worker.lock().expect("worker mutex poisoned").take() {
            let _ = worker.join();
        }
    }
}

#[derive(Clone)]
pub struct PocheClient {
    inner: Arc<ClientInner>,
}

impl PocheClient {
    pub fn connect(config: ClientConfig, timeout: Duration) -> Result<Self, ClientError> {
        let (event_tx, event_rx) = mpsc::channel();
        let lifecycle = Arc::new((
            Mutex::new(Lifecycle {
                state: ConnectionState::Connecting,
                identity: None,
            }),
            Condvar::new(),
        ));
        let credential_key = credential_key(&config);
        let token = credentials::File::new(&credential_key)
            .load()
            .map_err(|error| ClientError::Credentials(error.to_string()))?;

        let connected_lifecycle = Arc::clone(&lifecycle);
        let connected_tx = event_tx.clone();
        let connected_credential_key = credential_key.clone();
        let error_lifecycle = Arc::clone(&lifecycle);
        let error_tx = event_tx.clone();
        let disconnected_lifecycle = Arc::clone(&lifecycle);
        let disconnected_tx = event_tx.clone();

        let connection = DbConnection::builder()
            .on_connect(move |_ctx, identity: Identity, token: &str| {
                if let Err(error) = credentials::File::new(&connected_credential_key).save(token) {
                    let _ = connected_tx.send(ClientEvent::Error(format!(
                        "failed to save profile credential: {error}"
                    )));
                }
                let identity = identity.to_hex().to_string();
                let (state, wake) = &*connected_lifecycle;
                let mut state = state.lock().expect("lifecycle mutex poisoned");
                state.state = ConnectionState::Connected;
                state.identity = Some(identity.clone());
                wake.notify_all();
                let _ = connected_tx.send(ClientEvent::Connected { identity });
            })
            .on_connect_error(move |_ctx, error| {
                let message = error.to_string();
                let (state, wake) = &*error_lifecycle;
                state.lock().expect("lifecycle mutex poisoned").state =
                    ConnectionState::Failed(message.clone());
                wake.notify_all();
                let _ = error_tx.send(ClientEvent::Error(message));
            })
            .on_disconnect(move |_ctx, error| {
                let reason = error.map(|error| error.to_string());
                let (state, wake) = &*disconnected_lifecycle;
                state.lock().expect("lifecycle mutex poisoned").state =
                    ConnectionState::Disconnected;
                wake.notify_all();
                let _ = disconnected_tx.send(ClientEvent::Disconnected { reason });
            })
            .with_token(token)
            .with_database_name(config.database)
            .with_uri(config.uri)
            .build()
            .map_err(|error| ClientError::Connect(error.to_string()))?;

        register_change_callbacks(&connection, event_tx.clone());
        subscribe(&connection, Arc::clone(&lifecycle), event_tx.clone());
        let worker = connection.run_threaded();
        let client = Self {
            inner: Arc::new(ClientInner {
                connection,
                worker: Mutex::new(Some(worker)),
                lifecycle,
                event_tx,
                event_rx: Mutex::new(event_rx),
                next_request: AtomicU64::new(1),
            }),
        };
        client.wait_until_ready(timeout)?;
        Ok(client)
    }

    pub fn wait_until_ready(&self, timeout: Duration) -> Result<(), ClientError> {
        let deadline = Instant::now() + timeout;
        let (state, wake) = &*self.inner.lifecycle;
        let mut state = state.lock().expect("lifecycle mutex poisoned");
        loop {
            match &state.state {
                ConnectionState::Ready => return Ok(()),
                ConnectionState::Failed(message) => {
                    return Err(ClientError::Connect(message.clone()));
                }
                ConnectionState::Disconnected => {
                    return Err(ClientError::Connect("disconnected before ready".into()));
                }
                ConnectionState::Connecting | ConnectionState::Connected => {}
            }
            let now = Instant::now();
            if now >= deadline {
                return Err(ClientError::Timeout(
                    "waiting for initial subscription".into(),
                ));
            }
            let (new_state, wait) = wake
                .wait_timeout(state, deadline.saturating_duration_since(now))
                .expect("lifecycle mutex poisoned while waiting");
            state = new_state;
            if wait.timed_out() && !matches!(state.state, ConnectionState::Ready) {
                return Err(ClientError::Timeout(
                    "waiting for initial subscription".into(),
                ));
            }
        }
    }

    #[must_use]
    pub fn connection_state(&self) -> ConnectionState {
        self.inner
            .lifecycle
            .0
            .lock()
            .expect("lifecycle mutex poisoned")
            .state
            .clone()
    }

    #[must_use]
    pub fn snapshot(&self) -> ClientSnapshot {
        snapshot_from(&self.inner.connection)
    }

    #[must_use]
    pub fn drain_events(&self) -> Vec<ClientEvent> {
        let receiver = self
            .inner
            .event_rx
            .lock()
            .expect("event receiver mutex poisoned");
        receiver.try_iter().collect()
    }

    pub fn create_room(&self, display_name: String) -> Result<RoomCapability, ClientError> {
        let capability = RoomCapability::generate()?;
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .create_room_then(
                capability.room_id.clone(),
                capability.join_code.clone(),
                display_name,
                move |_ctx, result| finish_command(&tx, request_id, "create_room", started, result),
            )
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(capability)
    }

    pub fn join_room(&self, join_code: String, display_name: String) -> Result<u64, ClientError> {
        if !valid_join_code(&join_code) {
            return Err(ClientError::Request(
                "join code has an invalid shape".into(),
            ));
        }
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .join_room_then(join_code, display_name, move |_ctx, result| {
                finish_command(&tx, request_id, "join_room", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    pub fn take_seat(&self, room_id: String, seat: u8) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .take_seat_then(room_id, seat, move |_ctx, result| {
                finish_command(&tx, request_id, "take_seat", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    pub fn release_seat(&self, room_id: String) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .release_seat_then(room_id, move |_ctx, result| {
                finish_command(&tx, request_id, "release_seat", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    #[allow(clippy::too_many_arguments)]
    pub fn set_card_pose(
        &self,
        room_id: String,
        card_id: String,
        sequence: u64,
        position_mm: [i32; 3],
        rotation_mdeg: [i32; 3],
    ) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .set_card_pose_then(
                room_id,
                card_id,
                sequence,
                position_mm[0],
                position_mm[1],
                position_mm[2],
                rotation_mdeg[0],
                rotation_mdeg[1],
                rotation_mdeg[2],
                move |_ctx, result| {
                    finish_command(&tx, request_id, "set_card_pose", started, result);
                },
            )
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    pub fn bid(&self, room_id: String, tricks: u8) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .bid_then(room_id, tricks, move |_ctx, result| {
                finish_command(&tx, request_id, "bid", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    pub fn play_card(&self, room_id: String, card_id: String) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .play_card_then(room_id, card_id, move |_ctx, result| {
                finish_command(&tx, request_id, "play_card", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    pub fn leave_room(&self, room_id: String) -> Result<u64, ClientError> {
        let request_id = self.next_request();
        let started = Instant::now();
        let tx = self.inner.event_tx.clone();
        self.inner
            .connection
            .reducers
            .leave_room_then(room_id, move |_ctx, result| {
                finish_command(&tx, request_id, "leave_room", started, result);
            })
            .map_err(|error| ClientError::Request(error.to_string()))?;
        Ok(request_id)
    }

    fn next_request(&self) -> u64 {
        self.inner.next_request.fetch_add(1, Ordering::Relaxed)
    }
}

fn register_change_callbacks(connection: &DbConnection, event_tx: mpsc::Sender<ClientEvent>) {
    let tx = event_tx.clone();
    connection.db.my_room_capability().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection
        .db
        .my_room_capability()
        .on_update(move |_, _, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    let tx = event_tx.clone();
    connection.db.my_room_capability().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.my_rooms().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.my_rooms().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.room_members().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.room_members().on_update(move |_, _, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.room_members().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.my_hand().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.my_hand().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.visible_card_poses().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection
        .db
        .visible_card_poses()
        .on_update(move |_, _, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    let tx = event_tx.clone();
    connection.db.visible_card_poses().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.visible_room_games().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection
        .db
        .visible_room_games()
        .on_update(move |_, _, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    let tx = event_tx.clone();
    connection.db.visible_room_games().on_delete(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection
        .db
        .visible_revealed_cards()
        .on_insert(move |_, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    let tx = event_tx.clone();
    connection
        .db
        .visible_revealed_cards()
        .on_delete(move |_, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    let tx = event_tx.clone();
    connection
        .db
        .visible_revealed_cards()
        .on_update(move |_, _, _| {
            let _ = tx.send(ClientEvent::ModelChanged);
        });
    register_activity_callbacks(connection, event_tx);
}

fn register_activity_callbacks(connection: &DbConnection, event_tx: mpsc::Sender<ClientEvent>) {
    let tx = event_tx.clone();
    connection.db.visible_activity().on_insert(move |_, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    let tx = event_tx.clone();
    connection.db.visible_activity().on_update(move |_, _, _| {
        let _ = tx.send(ClientEvent::ModelChanged);
    });
    connection.db.visible_activity().on_delete(move |_, _| {
        let _ = event_tx.send(ClientEvent::ModelChanged);
    });
}

fn subscribe(
    connection: &DbConnection,
    lifecycle: Arc<(Mutex<Lifecycle>, Condvar)>,
    event_tx: mpsc::Sender<ClientEvent>,
) {
    let ready_tx = event_tx.clone();
    connection
        .subscription_builder()
        .on_applied(move |_| {
            let (state, wake) = &*lifecycle;
            state.lock().expect("lifecycle mutex poisoned").state = ConnectionState::Ready;
            wake.notify_all();
            let _ = ready_tx.send(ClientEvent::Ready);
        })
        .on_error(move |_ctx, error| {
            let _ = event_tx.send(ClientEvent::Error(format!("subscription failed: {error}")));
        })
        .add_query(|query| query.from.my_room_capability())
        .add_query(|query| query.from.my_rooms())
        .add_query(|query| query.from.room_members())
        .add_query(|query| query.from.my_hand())
        .add_query(|query| query.from.visible_card_poses())
        .add_query(|query| query.from.visible_room_games())
        .add_query(|query| query.from.visible_revealed_cards())
        .add_query(|query| query.from.visible_activity())
        .subscribe();
}

fn snapshot_from(context: &DbConnection) -> ClientSnapshot {
    let identity = context
        .try_identity()
        .map(|identity| identity.to_hex().to_string());
    let room_capability = room_capability_from(context);
    let rooms = context
        .db
        .my_rooms()
        .iter()
        .map(|room| RoomView {
            room_id: room.room_id,
        })
        .collect();
    let mut members = context
        .db
        .room_members()
        .iter()
        .map(|member| {
            let member_identity = member.identity.to_hex().to_string();
            MemberView {
                is_self: identity.as_deref() == Some(member_identity.as_str()),
                identity: member_identity,
                display_name: member.display_name,
                seat: member.seat,
                connected: member.connected,
            }
        })
        .collect::<Vec<_>>();
    members.sort_by(|left, right| left.identity.cmp(&right.identity));
    let mut hand = context
        .db
        .my_hand()
        .iter()
        .map(|card| HandCardView {
            card_key: card.card_key,
            card_id: card.card_id,
            face: card.face,
        })
        .collect::<Vec<_>>();
    hand.sort_by(|left, right| left.card_key.cmp(&right.card_key));
    let mut card_poses = context
        .db
        .visible_card_poses()
        .iter()
        .map(|pose| CardPoseView {
            card_key: pose.card_key,
            card_id: pose.card_id,
            owner: pose.owner.to_hex().to_string(),
            owner_seat: pose.owner_seat,
            logical_location: pose.logical_location,
            position_mm: [pose.x_mm, pose.y_mm, pose.z_mm],
            rotation_mdeg: [pose.rx_mdeg, pose.ry_mdeg, pose.rz_mdeg],
            sequence: pose.sequence,
        })
        .collect::<Vec<_>>();
    card_poses.sort_by(|left, right| left.card_key.cmp(&right.card_key));
    let game = context
        .db
        .visible_room_games()
        .iter()
        .next()
        .map(|game| GameView {
            phase: game.phase,
            actor_seat: game.actor_seat,
            dealer_seat: game.dealer_seat,
            round_index: game.round_index,
            hand_size: game.hand_size,
            hand_counts: [game.hand_count_0, game.hand_count_1],
            bids: [game.bid_0, game.bid_1],
            trick_count: game.trick_count,
            trick_seats: [game.trick_seat_0, game.trick_seat_1],
            trick_cards: [game.trick_card_0, game.trick_card_1],
            tricks_won: [game.tricks_won_0, game.tricks_won_1],
            scores: [game.score_0, game.score_1],
            pot_cents: game.pot_cents,
            trump: game.trump,
            action_count: game.action_count,
        });
    let mut revealed_cards = context
        .db
        .visible_revealed_cards()
        .iter()
        .map(|card| RevealedCardView {
            card_key: card.card_key,
            face: card.face,
        })
        .collect::<Vec<_>>();
    revealed_cards.sort_by(|left, right| left.card_key.cmp(&right.card_key));
    let activity = activity_from(context);
    ClientSnapshot {
        identity,
        room_capability,
        rooms,
        members,
        hand,
        card_poses,
        game,
        revealed_cards,
        activity,
    }
}

fn activity_from(context: &DbConnection) -> Vec<ActivityView> {
    let mut activity = context
        .db
        .visible_activity()
        .iter()
        .map(|event| ActivityView {
            sequence: event.sequence,
            kind: event.kind,
            summary: event.summary,
        })
        .collect::<Vec<_>>();
    activity.sort_by_key(|event| event.sequence);
    activity
}

fn room_capability_from(context: &DbConnection) -> Option<RoomCapability> {
    context
        .db
        .my_room_capability()
        .iter()
        .next()
        .map(|capability| RoomCapability {
            room_id: capability.room_id,
            join_code: capability.join_code,
        })
}

fn finish_command<RemoteError: fmt::Display>(
    tx: &mpsc::Sender<ClientEvent>,
    request_id: u64,
    operation: &'static str,
    started: Instant,
    result: Result<Result<(), String>, RemoteError>,
) {
    let result = match result {
        Ok(result) => result,
        Err(error) => Err(error.to_string()),
    };
    let _ = tx.send(ClientEvent::CommandFinished {
        request_id,
        operation,
        elapsed: started.elapsed(),
        result,
    });
}

fn credential_key(config: &ClientConfig) -> String {
    let account = blake3::hash(config.account_id.as_bytes()).to_hex();
    if config.uri.trim_end_matches('/') == DEFAULT_URI && config.database == DEFAULT_DATABASE {
        return format!("poche-spacetimedb-{}", &account.as_str()[..32]);
    }
    let scope = blake3::hash(
        format!("{}\0{}", config.uri.trim_end_matches('/'), config.database).as_bytes(),
    )
    .to_hex();
    format!(
        "poche-spacetimedb-{}-{}",
        &scope.as_str()[..16],
        &account.as_str()[..32]
    )
}

fn encode_hex(bytes: &[u8], uppercase: bool) -> String {
    const LOWER: &[u8; 16] = b"0123456789abcdef";
    const UPPER: &[u8; 16] = b"0123456789ABCDEF";
    let digits = if uppercase { UPPER } else { LOWER };
    let mut result = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        result.push(char::from(digits[usize::from(byte >> 4)]));
        result.push(char::from(digits[usize::from(byte & 0x0f)]));
    }
    result
}

#[must_use]
pub fn valid_join_code(value: &str) -> bool {
    let bytes = value.as_bytes();
    bytes.len() == 23
        && bytes.starts_with(b"PCH-")
        && [3, 8, 13, 18].into_iter().all(|index| bytes[index] == b'-')
        && bytes.iter().enumerate().all(|(index, byte)| {
            index < 4 || [8, 13, 18].contains(&index) || byte.is_ascii_hexdigit()
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_capability_has_valid_opaque_shape() {
        let capability = RoomCapability::generate().expect("random capability");
        assert!(capability.room_id.starts_with("room-"));
        assert!(valid_join_code(&capability.join_code));
    }

    #[test]
    fn invalid_join_codes_are_rejected_before_network_use() {
        assert!(!valid_join_code("PCH-ALICE"));
        assert!(!valid_join_code("PCH-0000-0000-0000-000Z"));
        assert!(!valid_join_code("PCH0000000000000000"));
    }

    #[test]
    fn immutable_account_credentials_are_scoped_by_authority() {
        let local = ClientConfig {
            uri: DEFAULT_URI.into(),
            database: DEFAULT_DATABASE.into(),
            account_id: "account-alice".into(),
        };
        let hosted = ClientConfig {
            uri: "https://maincloud.spacetimedb.com".into(),
            database: "poche-6quz6".into(),
            account_id: "account-alice".into(),
        };
        let staging = ClientConfig {
            database: "poche-staging".into(),
            ..hosted.clone()
        };
        let punctuation_variant = ClientConfig {
            account_id: "accountalice".into(),
            ..local.clone()
        };
        assert_eq!(
            credential_key(&local).len(),
            "poche-spacetimedb-".len() + 32
        );
        assert_ne!(credential_key(&local), credential_key(&punctuation_variant));
        assert_ne!(credential_key(&hosted), credential_key(&local));
        assert_ne!(credential_key(&hosted), credential_key(&staging));
    }
}
